/**
 * Check that the square brackets in `text` are balanced.
 *
 * @param text - to be verified
 * @returns `true` if the check passes
 */
export function hasBalancedBrackets(text: string): boolean {
  let depth = 0;
  for (const character of text) {
    if (character === "[") {
      depth++;
    } else if (character === "]") {
      depth--;
      if (depth < 0) {
        return false;
      }
    }
  }

  return depth === 0;
}

/**
 * Check that the `texts` do not repeat.
 *
 * @param texts - to be verified
 * @returns `true` if the check passes
 */
export function textsAreUnique(texts: Iterable<string>): boolean {
  const textSet = new Set<string>();
  for (const text of texts) {
    if (textSet.has(text)) {
      return false;
    }

    textSet.add(text);
  }

  return true;
}

/**
 * Check that {@link types.IItem.label}'s of the `items` do not repeat.
 *
 * @param items - to be verified
 * @returns `true` if the check passes
 */
export function itemsHaveUniqueLabels(
  items: Iterable<AasTypes.IItem>
): boolean {
  const labelSet = new Set<string>();
  for (const item of items) {
    if (labelSet.has(item.label)) {
      return false;
    }

    labelSet.add(item.label);
  }

  return true;
}

